themes.css:
:root {
  --acme-color-background: #ffffff;
  --acme-color-surface: #fafafa;
  --acme-color-border: #d9d9d9;
  --acme-color-foreground: #505050;
  --acme-color-foreground-muted: #6e6e6e;
  --acme-color-surface-raised: #f5f5f5;
  --acme-color-surface-overlay: #ffffff;
  --acme-color-surface-sunken: #f2f2f2;
  --acme-color-primary: #2067d9;
  --acme-color-foreground-on-accent: #f8f8f8;
  --acme-color-primary-hover: #0c58c8;
  --acme-color-primary-active: #004ab2;
  --acme-color-primary-subtle: #e5efff;
  --acme-color-primary-surface: #276ee0;
  --acme-color-accent: #6b7300;
  --acme-color-accent-hover: #5d6400;
  --acme-color-accent-active: #4f5600;
  --acme-color-accent-subtle: #edf4c6;
  --acme-color-accent-surface: #707800;
  --acme-color-danger: #d52727;
  --acme-color-info: #0075af;
  --acme-color-success: #007f47;
  --acme-color-warning: #966500;
  --acme-color-primary-surface-hover: #155ecf;
  --acme-color-accent-surface-hover: #616900;
  --acme-color-danger-surface: #da2d2c;
  --acme-color-danger-surface-hover: #c8111a;
  --acme-color-info-surface: #0079b4;
  --acme-color-info-surface-hover: #006a9f;
  --acme-color-success-surface: #00834a;
  --acme-color-success-surface-hover: #007340;
  --acme-color-warning-surface: #9c6800;
  --acme-color-warning-surface-hover: #895b00;
  --acme-color-surface-inverse: #161616;
  --acme-color-foreground-inverse: #a4a4a4;
  --acme-color-focus-ring: #4289fe;
  --acme-color-brand-mark: #3b82f6;
  --acme-seed-brand: #2067d9;
  --acme-seed-chroma-scale: 1;
  --acme-seed-density: 1;
  --acme-seed-radii: 0.5rem;
  --acme-border-surface: 0;
  --acme-shadow-surface: 0 4px 12px color-mix(in oklab, oklch(0.13 0 0) 10%, transparent);
  --acme-border-floating: 0;
  --acme-shadow-floating: 0 12px 32px color-mix(in oklab, oklch(0.13 0 0) 14%, transparent);
  /* Assumes these faces are already loaded. */
  --acme-font-sans: Inter;
  --acme-font-display: Inter;
  --acme-font-mono: Berkeley Mono;
  --acme-duration-fast: 158ms;
  --acme-duration-normal: 264ms;
  --acme-duration-slow: 422ms;
  --acme-easing-standard: var(--acme-easing-spring);
  --acme-easing-emphasized: var(--acme-easing-spring);
  --acme-easing-decelerate: var(--acme-easing-spring);
  --acme-text-2xl: 1.9375rem;
  --acme-text-3xl: 2.4375rem;
  --acme-text-lg: 1.25rem;
  --acme-text-md: 1rem;
  --acme-text-sm: 0.9375rem;
  --acme-text-xl: 1.5625rem;
  --acme-text-xs: 0.875rem;
  --acme-weight-medium: 600;
  --acme-weight-regular: 500;
  --acme-weight-semibold: 700;
  --acme-material-backdrop: blur(12px);
  --acme-material-translucent: color-mix(in oklab, var(--acme-color-surface) 72%, transparent);
  --acme-material-opacity: 0.72;
}

:root {
  --helix-color-background: #ffffff;
  --helix-color-surface: #fafafa;
  --helix-color-border: #d9d9d9;
  --helix-color-foreground: #505050;
  --helix-color-foreground-muted: #6e6e6e;
  --helix-color-surface-raised: #f5f5f5;
  --helix-color-surface-overlay: #ffffff;
  --helix-color-surface-sunken: #f2f2f2;
  --helix-color-primary: #2067d9;
  --helix-color-foreground-on-accent: #f8f8f8;
  --helix-color-primary-hover: #0c58c8;
  --helix-color-primary-active: #004ab2;
  --helix-color-primary-subtle: #e5efff;
  --helix-color-primary-surface: #276ee0;
  --helix-color-accent: #6b7300;
  --helix-color-accent-hover: #5d6400;
  --helix-color-accent-active: #4f5600;
  --helix-color-accent-subtle: #edf4c6;
  --helix-color-accent-surface: #707800;
  --helix-color-danger: #d52727;
  --helix-color-info: #0075af;
  --helix-color-success: #007f47;
  --helix-color-warning: #966500;
  --helix-color-primary-surface-hover: #155ecf;
  --helix-color-accent-surface-hover: #616900;
  --helix-color-danger-surface: #da2d2c;
  --helix-color-danger-surface-hover: #c8111a;
  --helix-color-info-surface: #0079b4;
  --helix-color-info-surface-hover: #006a9f;
  --helix-color-success-surface: #00834a;
  --helix-color-success-surface-hover: #007340;
  --helix-color-warning-surface: #9c6800;
  --helix-color-warning-surface-hover: #895b00;
  --helix-color-surface-inverse: #161616;
  --helix-color-foreground-inverse: #a4a4a4;
  --helix-color-focus-ring: #4289fe;
  --helix-color-brand-mark: #3b82f6;
  --helix-seed-brand: #2067d9;
  --helix-seed-chroma-scale: 1;
  --helix-seed-density: 1;
  --helix-seed-radii: 0.5rem;
  --helix-border-floating: 1px;
  --helix-shadow-floating: none;
  /* Assumes these faces are already loaded. */
  --helix-font-display: Playfair Display;
  --helix-duration-fast: 60ms;
  --helix-duration-normal: 100ms;
  --helix-duration-slow: 160ms;
  --helix-weight-medium: 400;
  --helix-weight-regular: 300;
  --helix-weight-semibold: 500;
  --helix-material-backdrop: none;
  --helix-material-translucent: color-mix(in oklab, var(--helix-color-surface) 100%, transparent);
  --helix-material-opacity: 1;
}
